ALTER TABLE "valuation_records" ADD CONSTRAINT "valuation_records_prices" CHECK (("valuation_records"."estimated_market_value" IS NULL OR "valuation_records"."estimated_market_value" > 0) AND ("valuation_records"."market_min" IS NULL AND "valuation_records"."market_max" IS NULL OR "valuation_records"."market_min" IS NOT NULL AND "valuation_records"."market_max" IS NOT NULL AND "valuation_records"."market_min" > 0 AND "valuation_records"."market_max" >= "valuation_records"."market_min") AND ("valuation_records"."buying_min" IS NULL AND "valuation_records"."buying_max" IS NULL OR "valuation_records"."buying_min" IS NOT NULL AND "valuation_records"."buying_max" IS NOT NULL AND "valuation_records"."buying_min" > 0 AND "valuation_records"."buying_max" >= "valuation_records"."buying_min"));